use moloch_live_runtime::{package_settings::{Settings,Bundle},authority::Activation,relationship_strategy::*};
use baal_transport_service::Scope;
use sha2::{Digest,Sha256};
use std::{collections::BTreeSet,fs,path::PathBuf};
const T:&str="11111111-1111-4111-8111-111111111111";
fn scope()->Scope{Scope{tournament_id:T.into(),tournament_slug:"cup".into(),exchanges:[("101".into(),"201".into()),("102".into(),"202".into())].into()}}
fn cert()->SettlementCertificate{SettlementCertificate{version:2,tournament_id:T.into(),relationship_id:"22222222-2222-4222-8222-222222222222".into(),relationship_version:1,canonical_relationship_sha256:"a".repeat(64),relationship_receipt_sha256:"b".repeat(64),issued_at_ms:1000,expires_at_ms:100_000,verifier_id:"settings-fixture-not-execution-authority".into(),logic:CertifiedLogic::MutuallyExclusive{exhaustive:false},contracts:(0..2).map(|i|ContractCertificate{exchange_id:(101+i).to_string(),market_id:(201+i).to_string(),contract_id:(301+i).to_string(),canonical_outcome:"YES".into(),rule_receipt_sha256:"c".repeat(64),rule_endpoint:format!("/markets/{}/nodes?tournamentId={T}",201+i),rule_data_sha256:Some("d".repeat(64)),ordinary_yes_payout:"1".into(),ordinary_no_payout:"0".into(),ordinary_no_yes_payout:"0".into(),ordinary_no_no_payout:"1".into(),terminal_rules_complete:true,exceptions:vec![]}).collect()}}
struct Fixture{path:PathBuf,s:Settings}
impl Fixture{fn new()->Self{let path=std::env::temp_dir().join(format!("package-settings-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));fs::create_dir(&path).unwrap();let file=path.join("reviewed-bundle.json");let bytes=serde_json::to_vec(&Bundle{certificates:vec![cert()],original_receipts:vec![]}).unwrap();fs::write(&file,&bytes).unwrap();Self{path,s:Settings{certificate_bundle:file,bundle_sha256:format!("{:x}",Sha256::digest(&bytes)),trusted_certificate_sha256:BTreeSet::new(),refresh_ms:60_000,maximum_relationship_age_ms:120_000,maximum_rule_age_ms:3_600_000,buffer_per_share:"0.005000".into(),minimum_surplus:"0.000001".into()}}}fn repin(&mut self,b:&Bundle){let bytes=serde_json::to_vec(b).unwrap();fs::write(&self.s.certificate_bundle,&bytes).unwrap();self.s.bundle_sha256=format!("{:x}",Sha256::digest(bytes));}}
impl Drop for Fixture{fn drop(&mut self){let _=fs::remove_dir_all(&self.path);}}
#[test]fn loading_never_self_approves_and_only_current_independent_hashes_are_selected(){let mut f=Fixture::new();let b=f.s.load(&scope()).unwrap();assert_eq!(b.certificates.len(),1);assert!(f.s.approved(&b,2000).unwrap().is_empty());f.s.trusted_certificate_sha256.insert(certificate_sha256(&cert()).unwrap());let b=f.s.load(&scope()).unwrap();assert_eq!(f.s.approved(&b,1000).unwrap().len(),1);assert!(f.s.approved(&b,999).unwrap().is_empty());assert!(f.s.approved(&b,100_000).unwrap().is_empty());}
#[test]fn changed_bytes_missing_approval_duplicate_certificate_and_wrong_scope_reject(){let mut f=Fixture::new();let original=fs::read(&f.s.certificate_bundle).unwrap();fs::write(&f.s.certificate_bundle,b"{}").unwrap();assert!(f.s.load(&scope()).is_err());fs::write(&f.s.certificate_bundle,original).unwrap();f.s.trusted_certificate_sha256.insert("f".repeat(64));assert!(f.s.load(&scope()).is_err());f.s.trusted_certificate_sha256.clear();f.repin(&Bundle{certificates:vec![cert(),cert()],original_receipts:vec![]});assert!(f.s.load(&scope()).is_err());let mut changed=cert();changed.contracts[0].market_id="999".into();f.s.trusted_certificate_sha256=[certificate_sha256(&changed).unwrap()].into();f.repin(&Bundle{certificates:vec![changed],original_receipts:vec![]});assert!(f.s.load(&scope()).is_err());}
#[test]fn policy_quantities_use_original_total_cap_for_each_component_count(){let f=Fixture::new();let a=Activation{run_id:"run".into(),entry_until_ms:100_000,maximum_committed:"40000.000000".into(),maximum_market_cost:"10000.000000".into(),maximum_quantity:10000,tournament_id:T.into(),tournament_slug:"cup".into(),binary_sha256:"b".repeat(64)};for n in [2,3]{let p=f.s.policy(&a,2000,n).unwrap();assert_eq!(p.maximum_quantity,10000/n as u64);assert_eq!(p.quantities.last(),Some(&p.maximum_quantity));assert!(p.quantities.iter().all(|q|q*n as u64<=a.maximum_quantity as u64));assert!(p.quantities.windows(2).all(|w|w[0]<w[1]));assert_eq!(p.max_book_age_ms,10000);}assert!(f.s.policy(&a,2000,4).is_err());}
#[test]fn invalid_bounds_margin_hash_and_relative_path_reject_before_loading(){for mode in 0..6{let mut f=Fixture::new();match mode{0=>f.s.refresh_ms=0,1=>f.s.maximum_relationship_age_ms=1,2=>f.s.maximum_rule_age_ms=u64::MAX,3=>f.s.minimum_surplus="0.000000".into(),4=>f.s.bundle_sha256="BAD".into(),_=>f.s.certificate_bundle="relative.json".into()};assert!(f.s.validate().is_err());}}
#[cfg(unix)]#[test]fn symlink_bundle_is_never_used_even_with_correct_bytes(){let mut f=Fixture::new();let link=f.path.join("link.json");std::os::unix::fs::symlink(&f.s.certificate_bundle,&link).unwrap();f.s.certificate_bundle=link;assert!(f.s.load(&scope()).is_err());}
